INSERT INTO `timeline` (`id`, `year`, `title`, `description`, `sort_order`, `created_at`) VALUES
(1,	'1987',	'प्रादेशिक विकास दल विभाग द्वारा आयोजित क्षेत्रीय युवक खेककूद समारोह (26-12-1987) में प्रतिभाग कर वॉलीबॉल प्रतियोगिता में द्वितीय तथा 800 मीटर दौड़ में तृतीय पुरस्कार प्राप्त किया।',	NULL,	0,	'2026-04-25 09:49:19'),
(2,	'1987',	'युवा कल्याण विभाग द्वारा 26-12-1987 को आयोजित खंड स्तरीय युवा विचार गोष्ठी में एक वर्ष की युवक मंगल दल की अनेक गतिविधियों की दृष्टिगत \"अनुशासित युवक\" घोषित किया गया एवं खण्ड विकास अधिकारी बंकी, द्वारा पुरस्कृत किया गया।',	NULL,	0,	'2026-04-25 09:50:53'),
(3,	'1987',	'खेलकूद प्रतियोगिता पुरस्कार',	'वॉलीबॉल में द्वितीय एवं 800 मीटर दौड़ में तृतीय पुरस्कार',	1,	'2026-04-25 10:08:33'),
(4,	'1987',	'अनुशासित युवक',	'युवा विचार गोष्ठी में अनुशासित युवक घोषित',	2,	'2026-04-25 10:08:33'),
(5,	'1988',	'खेलकूद प्रतियोगिता',	'800 मीटर दौड़ में तृतीय पुरस्कार',	3,	'2026-04-25 10:08:33'),
(6,	'1988',	'NSS गणतंत्र दिवस',	'राष्ट्रीय परेड में भाग लेकर प्रमाण पत्र प्राप्त',	4,	'2026-04-25 10:08:33'),
(7,	'1988',	'पॉवन माटी कार्यक्रम',	'जिलाधिकारी द्वारा प्रशस्ति पत्र एवं सम्मान',	5,	'2026-04-25 10:08:33'),
(8,	'1988',	'नेत्र चिकित्सा शिविर',	'सेवा कार्य हेतु प्रशस्ति पत्र',	6,	'2026-04-25 10:08:33'),
